// ---------------------------------------------------------------------------
// >>> tb/fido_tb_pkg.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_pkg.sv
// Package   : fido_tb_pkg
// Content   : bench constants, RV32IM instruction encoders, an independent
//             M-extension reference model, and domain / test names used in
//             the reports.
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

package fido_tb_pkg;
  import fido_pkg::*;

  //--------------------------------------------------------------- bench constants
  localparam int TIMEOUT = 200000;   // cycles per test
  localparam int FIFO_D  = 8192;     // scoreboard depth (REF ahead of DUT)
  localparam int BE_LBL  = 24;       // break-even idle length used for scoring (= ml/train_ml.py)
  localparam int MAX_EV  = 32;       // events per test

  //--------------------------------------------------------------- opcodes
  localparam logic [6:0] OP_R   = 7'b0110011;
  localparam logic [6:0] OP_I   = 7'b0010011;
  localparam logic [6:0] OP_LUI = 7'b0110111;
  localparam logic [6:0] OP_AUI = 7'b0010111;
  localparam logic [6:0] OP_JAL = 7'b1101111;
  localparam logic [6:0] OP_JR  = 7'b1100111;
  localparam logic [6:0] OP_BR  = 7'b1100011;
  localparam logic [6:0] OP_LD  = 7'b0000011;
  localparam logic [6:0] OP_ST  = 7'b0100011;
  localparam logic [6:0] OP_SYS = 7'b1110011;

  localparam logic [31:0] I_ECALL  = 32'h0000_0073;
  localparam logic [31:0] I_EBREAK = 32'h0010_0073;
  localparam logic [31:0] I_MRET   = 32'h3020_0073;
  localparam logic [31:0] I_WFI    = 32'h1050_0073;
  localparam logic [31:0] I_NOP    = 32'h0000_5013;   // srli x0,x0,0 (shift unit, neutral)

  //--------------------------------------------------------------- encoders
  function automatic logic [31:0] enc_r(input logic [6:0] f7, input logic [4:0] rs2,
                                        input logic [4:0] rs1, input logic [2:0] f3,
                                        input logic [4:0] rd, input logic [6:0] op);
    return {f7, rs2, rs1, f3, rd, op};
  endfunction

  function automatic logic [31:0] enc_i(input logic [11:0] imm, input logic [4:0] rs1,
                                        input logic [2:0] f3, input logic [4:0] rd,
                                        input logic [6:0] op);
    return {imm, rs1, f3, rd, op};
  endfunction

  function automatic logic [31:0] enc_s(input logic [11:0] imm, input logic [4:0] rs2,
                                        input logic [4:0] rs1, input logic [2:0] f3);
    return {imm[11:5], rs2, rs1, f3, imm[4:0], OP_ST};
  endfunction

  function automatic logic [31:0] enc_b(input logic [12:0] off, input logic [4:0] rs2,
                                        input logic [4:0] rs1, input logic [2:0] f3);
    return {off[12], off[10:5], rs2, rs1, f3, off[4:1], off[11], OP_BR};
  endfunction

  function automatic logic [31:0] enc_j(input logic [20:0] off, input logic [4:0] rd);
    return {off[20], off[10:1], off[11], off[19:12], rd, OP_JAL};
  endfunction

  //--------------------------------------------------------------- M-extension reference
  // independent of the RTL datapath (expected values of the self-checking programs)
  function automatic logic [31:0] ref_mdu(input logic [2:0] op, input logic [31:0] a,
                                          input logic [31:0] b);
    logic [63:0] sa;
    logic [63:0] sb;
    logic [63:0] za;
    logic [63:0] zb;
    logic [63:0] p;
    logic [31:0] r;
    sa = {{32{a[31]}}, a};
    sb = {{32{b[31]}}, b};
    za = {32'd0, a};
    zb = {32'd0, b};
    case (op)
      3'd0: begin p = za * zb; r = p[31:0];  end
      3'd1: begin p = sa * sb; r = p[63:32]; end
      3'd2: begin p = sa * zb; r = p[63:32]; end
      3'd3: begin p = za * zb; r = p[63:32]; end
      3'd4: begin
        if (b == 32'd0)                                         r = 32'hFFFF_FFFF;
        else if ((a == 32'h8000_0000) && (b == 32'hFFFF_FFFF)) r = 32'h8000_0000;
        else                                                    r = $signed(a) / $signed(b);
      end
      3'd5: begin
        if (b == 32'd0) r = 32'hFFFF_FFFF;
        else            r = a / b;
      end
      3'd6: begin
        if (b == 32'd0)                                         r = a;
        else if ((a == 32'h8000_0000) && (b == 32'hFFFF_FFFF)) r = 32'd0;
        else                                                    r = $signed(a) % $signed(b);
      end
      default: begin
        if (b == 32'd0) r = a;
        else            r = a % b;
      end
    endcase
    return r;
  endfunction

  //--------------------------------------------------------------- names (10 characters)
  function automatic string cg_name(input int grain, input int d);
    string s;
    s = "?         ";
    if (grain == 0) begin
      case (d)
        0:  s = "D_ADD     ";
        1:  s = "D_SHIFT   ";
        2:  s = "D_LOGIC   ";
        3:  s = "D_CMP     ";
        4:  s = "D_MUL     ";
        5:  s = "D_DIV     ";
        6:  s = "D_IDEX    ";
        7:  s = "D_EXMEM   ";
        8:  s = "D_MEMWB   ";
        9:  s = "D_BANK0   ";
        10: s = "D_BANK1   ";
        11: s = "D_BANK2   ";
        12: s = "D_BANK3   ";
        13: s = "D_RFHI    ";
        14: s = "D_EVQ     ";
        default: s = "?         ";
      endcase
    end else begin
      case (d)
        0: s = "D_EX      ";
        1: s = "D_MEM     ";
        2: s = "D_WB      ";
        3: s = "D_STORAGE ";
        4: s = "D_CORE    ";
        default: s = "?         ";
      endcase
    end
    return s;
  endfunction

  function automatic string pg_name(input int grain, input int d);
    string s;
    s = "?         ";
    if (grain == 0) begin
      case (d)
        0: s = "PD_ALU_HI ";
        1: s = "PD_MUL    ";
        2: s = "PD_DIV    ";
        3: s = "PD_BANK0  ";
        4: s = "PD_BANK1  ";
        5: s = "PD_BANK2  ";
        6: s = "PD_BANK3  ";
        7: s = "PD_RF_HI  ";
        default: s = "?         ";
      endcase
    end else begin
      case (d)
        0: s = "PD_EX     ";
        1: s = "PD_STORAGE";
        2: s = "PD_CORE   ";
        default: s = "?         ";
      endcase
    end
    return s;
  endfunction

  // name of observation slot d (MODE 3/4: slots 0..NCG-1 clock, then power domains)
  function automatic string dname(input int mode, input int grain, input int d);
    int ncg;
    ncg = (grain == 0) ? 15 : 5;
    if (mode == 1)                     return cg_name(grain, d);
    else if (mode == 2)                return pg_name(grain, d);
    else if ((mode >= 3) && (d < ncg)) return cg_name(grain, d);
    else if (mode >= 3)                return pg_name(grain, d - ncg);
    else                               return "?         ";
  endfunction

  //--------------------------------------------------------------- domain maps
  // number of observation slots of a configuration
  function automatic int n_slots(input int mode, input int grain);
    int ncg;
    int npg;
    ncg = (grain == 0) ? NCG_FINE : NCG_COARSE;
    npg = (grain == 0) ? NPG_FINE : NPG_COARSE;
    if (mode == MODE_CG)      return ncg;
    else if (mode == MODE_PG) return npg;
    else if (mode >= 3)       return ncg + npg;
    else                      return 0;
  endfunction

  // MODE 1 / 2: domain of clock net cn (31 = not gated)
  function automatic int cn2dom(input int mode, input int grain, input int cn);
    logic [89:0] map;
    if (mode == MODE_CG) map = (grain == 0) ? MAP_CG_F : MAP_CG_C;
    else                 map = (grain == 0) ? MAP_PG_F : MAP_PG_C;
    return int'(map[cn*5 +: 5]);
  endfunction

  // MODE 3 / 4: slot of the clock domain of clock net cn (31 = none)
  function automatic int cn2cg(input int grain, input int cn);
    logic [89:0] map;
    map = (grain == 0) ? MAP_CG_F : MAP_CG_C;
    return int'(map[cn*5 +: 5]);
  endfunction

  // MODE 3 / 4: slot of the power domain of clock net cn (31 = none)
  function automatic int cn2pg(input int grain, input int cn);
    logic [89:0] map;
    int          ncg;
    map = (grain == 0) ? MAP_PG_F : MAP_PG_C;
    ncg = (grain == 0) ? NCG_FINE : NCG_COARSE;
    if (map[cn*5 +: 5] == DOM_NONE) return 31;
    else                            return ncg + int'(map[cn*5 +: 5]);
  endfunction

  // slot d is a clock-gating domain
  function automatic bit is_cg_slot(input int mode, input int grain, input int d);
    int ncg;
    ncg = (grain == 0) ? NCG_FINE : NCG_COARSE;
    return (mode == MODE_CG) || ((mode >= 3) && (d < ncg));
  endfunction

  function automatic string test_name(input int t);
    case (t)
      1:       return "reset_smoke";
      2:       return "alu_fwd_branch";
      3:       return "mul_div";
      4:       return "compute_idle_wake";
      5:       return "short_idle_thrash";
      6:       return "bank_retention";
      7:       return "rf_hi_retention";
      8:       return "wfi_poll_sleep";
      9:       return "wfi_irq_trap";
      10:      return "traps_reset_gated";
      11:      return "random_stress";
      12:      return "ml_confident_wrong";
      13:      return "ml_low_confidence";
      14:      return "ml_sleep_class";
      15:      return "ml_periodic_pattern";
      default: return "cg_to_pg_escalation";
    endcase
  endfunction

endpackage : fido_tb_pkg

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> tb/fido_tb_programs.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_programs.sv
// Module    : fido_tb_programs
// Content   : stimulus generator - program memory image, a small RV32IM
//             assembler, the self-checking test programs T01..T16, the
//             peripheral-event plan and the gating expectations of each test.
//             Expected values are computed here, independently of the RTL
//             datapath. A failing check stores its check id to TOHOST.
//   T01..T11 run on every configuration; T12..T16 (ML / CG+PG tests) on
//   MODE 3 (CG+PG) and MODE 4 (CG+PG+ML).
// Hierarchy : tb_<cfg> > u_env (fido_tb_env) > u_prog
// Access    : the environment reads prog[], plen, exp_f[], exp_c[],
//             exp_pg_req, t_force and sets seed hierarchically.
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module fido_tb_programs
  import fido_pkg::*;
  import fido_tb_pkg::*;
#(
  parameter int MODE  = 0,
  parameter int GRAIN = 0
) (
  // event plan (read by the two event sources)
  output int           ev_n,
  output logic [1023:0] ev_dly_v,     // 32 x 32-bit delay (cycles of WFI sleep)
  output logic   [63:0] ev_src_v,     // 32 x 2-bit source
  output logic  [255:0] ev_dat_v      // 32 x 8-bit data
);
  //=========================================================== state
  // (no initial block: the environment builds the first program at time 0;
  //  declaration initialisers run before any process starts)
  logic [31:0] prog [1024];
  int          plen   = 0;
  int          chk_id = 0;
  integer      seed   = 1;     // T11 random seed, set by the environment (+SEED)
  // expectations (clock nets that must be gated at least once)
  int          exp_f [4];
  int          exp_c [4];
  logic        exp_pg_req;     // MODE 4: power layer must also gate (forced tests)
  logic  [1:0] t_force;        // ml_force value of the test

  //=========================================================== assembler
  task automatic emit(input logic [31:0] w);
    if (plen < 1024) prog[plen] = w;
    plen = plen + 1;
  endtask

  task automatic a_r(input logic [6:0] f7, input logic [2:0] f3, input logic [4:0] rd,
                     input logic [4:0] rs1, input logic [4:0] rs2);      // R-type ALU / M
    emit(enc_r(f7, rs2, rs1, f3, rd, OP_R));
  endtask

  task automatic a_i(input logic [2:0] f3, input logic [4:0] rd, input logic [4:0] rs1,
                     input logic [11:0] imm);                            // I-type ALU
    emit(enc_i(imm, rs1, f3, rd, OP_I));
  endtask

  task automatic a_lui(input logic [4:0] rd, input logic [19:0] imm);
    emit({imm, rd, OP_LUI});
  endtask

  task automatic a_auipc(input logic [4:0] rd, input logic [19:0] imm);
    emit({imm, rd, OP_AUI});
  endtask

  task automatic a_ld(input logic [2:0] f3, input logic [4:0] rd, input logic [4:0] rs1,
                      input logic [11:0] off);
    emit(enc_i(off, rs1, f3, rd, OP_LD));
  endtask

  task automatic a_st(input logic [2:0] f3, input logic [4:0] rs2, input logic [4:0] rs1,
                      input logic [11:0] off);
    emit(enc_s(off, rs2, rs1, f3));
  endtask

  task automatic a_br(input logic [2:0] f3, input logic [4:0] rs1, input logic [4:0] rs2,
                      input integer target);                             // to absolute word index
    logic [31:0] off;
    off = (target - plen) * 4;
    emit(enc_b(off[12:0], rs2, rs1, f3));
  endtask

  task automatic a_jal(input logic [4:0] rd, input integer target);
    logic [31:0] off;
    off = (target - plen) * 4;
    emit(enc_j(off[20:0], rd));
  endtask

  task automatic a_jalr(input logic [4:0] rd, input logic [4:0] rs1, input logic [11:0] imm);
    emit(enc_i(imm, rs1, 3'd0, rd, OP_JR));
  endtask

  task automatic a_csr(input logic [2:0] f3, input logic [4:0] rd, input logic [11:0] csr,
                       input logic [4:0] rs1);                           // 1 RW 2 RS 3 RC 5 RWI 6 RSI 7 RCI
    emit(enc_i(csr, rs1, f3, rd, OP_SYS));
  endtask

  task automatic a_li(input logic [4:0] rd, input logic [31:0] v);
    logic [31:0] hi;
    if (($signed(v) >= -2048) && ($signed(v) <= 2047)) begin
      a_i(3'd0, rd, 5'd0, v[11:0]);
    end else begin
      hi = v + 32'h0000_0800;
      a_lui(rd, hi[31:12]);
      if (v[11:0] != 12'd0) a_i(3'd0, rd, rd, v[11:0]);
    end
  endtask

  // check: if (rd != v) store check id to TOHOST (fail stub at word 1)
  task automatic check_eq(input logic [4:0] rd, input logic [31:0] v);
    logic [31:0] id;
    logic [11:0] id12;
    chk_id = chk_id + 1;
    id     = chk_id;
    id12   = 12'h100 + id[11:0];
    a_li(5'd14, v);
    a_i(3'd0, 5'd13, 5'd0, id12);
    a_br(3'd1, rd, 5'd14, 1);
  endtask

  // program frame: word 0 jumps to start, words 1..3 = fail stub
  task automatic prog_begin(input integer start);
    for (int i = 0; i < 1024; i++) prog[i] = 32'd0;
    plen   = 0;
    chk_id = 0;
    a_jal(5'd0, start);
    a_lui(5'd15, 20'h00030);                 // fail stub: x15 = TOHOST
    a_st(3'd2, 5'd13, 5'd15, 12'd0);         //            sw x13 -> TOHOST
    a_jal(5'd0, 3);                          //            spin
  endtask

  task automatic pad_to(input integer w);
    while (plen < w) emit(I_NOP);
  endtask

  task automatic prog_pass;
    a_i(3'd0, 5'd13, 5'd0, 12'd1);
    a_lui(5'd15, 20'h00030);
    a_st(3'd2, 5'd13, 5'd15, 12'd0);
    a_jal(5'd0, plen);
    emit(I_NOP);
    emit(I_NOP);
  endtask

  // idle loop using only LUI / SHIFT / CMP: ADD, LOGIC, MUL, DIV, banks and
  // RF-HI stay idle. inner = ib+1 iterations (ib >= 12), outer = ceil(32/s).
  task automatic idle_loop(input integer ib, input integer s);
    integer     outer;
    integer     inner;
    logic [19:0] li20;
    li20 = 20'd1 << (ib - 12);
    a_lui(5'd6, 20'h80000);
    outer = plen;
    a_lui(5'd5, li20);
    inner = plen;
    a_i(3'd5, 5'd5, 5'd5, 12'd1);                 // srli x5,x5,1
    a_br(3'd1, 5'd5, 5'd0, inner);                // bne  x5,x0,inner
    a_i(3'd5, 5'd6, 5'd6, s[11:0]);               // srli x6,x6,s
    a_br(3'd1, 5'd6, 5'd0, outer);                // bne  x6,x0,outer
    emit(I_NOP);
    emit(I_NOP);
  endtask

  // short gap of about 4*(k) cycles, needs x8 = 0x8000_0000
  task automatic gap(input integer k);
    integer     lp;
    logic [11:0] sh;
    sh = 31 - k;
    a_i(3'd5, 5'd5, 5'd8, sh);                    // srli x5,x8,31-k  -> 1<<k
    lp = plen;
    a_i(3'd5, 5'd5, 5'd5, 12'd1);
    a_br(3'd1, 5'd5, 5'd0, lp);
    emit(I_NOP);
    emit(I_NOP);
  endtask

  task automatic add_event(input integer dly, input integer src, input logic [7:0] dat);
    ev_dly_v[ev_n*32 +: 32] = dly;
    ev_src_v[ev_n*2 +: 2]   = src[1:0];
    ev_dat_v[ev_n*8 +: 8]   = dat;
    ev_n = ev_n + 1;
  endtask

  task automatic clear_plan;
    ev_n = 0;
    for (int i = 0; i < 4; i++) begin
      exp_f[i] = -1;
      exp_c[i] = -1;
    end
    exp_pg_req = 1'b0;
    t_force    = 2'd0;
  endtask

  //=========================================================== test programs
  // T01 reset + smoke
  task automatic build_t01;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    a_li(5'd1, 32'd5);
    a_li(5'd2, 32'd7);
    a_r(7'd0, 3'd0, 5'd3, 5'd1, 5'd2);             // add
    check_eq(5'd3, 32'd12);
    a_r(7'h20, 3'd0, 5'd4, 5'd2, 5'd1);            // sub
    check_eq(5'd4, 32'd2);
    a_lui(5'd10, 20'h00010);
    a_st(3'd2, 5'd3, 5'd10, 12'd0);
    a_ld(3'd2, 5'd7, 5'd10, 12'd0);
    check_eq(5'd7, 32'd12);
    prog_pass;
  endtask

  // T02 RV32I ALU, forwarding, load-use, byte/half memory, branches, jumps
  task automatic build_t02;
    logic [31:0] A, B, C, S, P, W;
    integer      nt, L;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    A = 32'h1234_5678; B = 32'h0F0F_0F0F; C = 32'hFFFF_FFFB; S = 32'd7;
    a_li(5'd1, A); a_li(5'd2, B); a_li(5'd3, C); a_li(5'd4, S);
    a_r(7'd0,  3'd0, 5'd5, 5'd1, 5'd2); check_eq(5'd5, A + B);
    a_r(7'h20, 3'd0, 5'd5, 5'd1, 5'd2); check_eq(5'd5, A - B);
    a_r(7'd0,  3'd4, 5'd5, 5'd1, 5'd2); check_eq(5'd5, A ^ B);
    a_r(7'd0,  3'd6, 5'd5, 5'd1, 5'd2); check_eq(5'd5, A | B);
    a_r(7'd0,  3'd7, 5'd5, 5'd1, 5'd2); check_eq(5'd5, A & B);
    a_r(7'd0,  3'd1, 5'd5, 5'd1, 5'd4); check_eq(5'd5, A << 7);
    a_r(7'd0,  3'd5, 5'd5, 5'd3, 5'd4); check_eq(5'd5, C >> 7);
    a_r(7'h20, 3'd5, 5'd5, 5'd3, 5'd4); check_eq(5'd5, $signed(C) >>> 7);
    a_r(7'd0,  3'd2, 5'd5, 5'd3, 5'd4); check_eq(5'd5, 32'd1);
    a_r(7'd0,  3'd3, 5'd5, 5'd3, 5'd4); check_eq(5'd5, 32'd0);
    a_i(3'd0, 5'd5, 5'd1, 12'hF9C);     check_eq(5'd5, A - 32'd100);
    a_i(3'd2, 5'd5, 5'd3, 12'hFFC);     check_eq(5'd5, 32'd1);
    a_i(3'd3, 5'd5, 5'd4, 12'hFFF);     check_eq(5'd5, 32'd1);
    a_i(3'd4, 5'd5, 5'd1, 12'h7FF);     check_eq(5'd5, A ^ 32'h0000_07FF);
    a_i(3'd6, 5'd5, 5'd2, 12'h0F0);     check_eq(5'd5, B | 32'h0000_00F0);
    a_i(3'd7, 5'd5, 5'd1, 12'h0FF);     check_eq(5'd5, A & 32'h0000_00FF);
    a_i(3'd1, 5'd5, 5'd1, 12'd3);       check_eq(5'd5, A << 3);
    a_i(3'd5, 5'd5, 5'd3, 12'd4);       check_eq(5'd5, C >> 4);
    a_i(3'd5, 5'd5, 5'd3, 12'h404);     check_eq(5'd5, $signed(C) >>> 4);
    a_lui(5'd5, 20'hABCDE);             check_eq(5'd5, 32'hABCD_E000);
    P = plen * 4;
    a_auipc(5'd5, 20'h00012);           check_eq(5'd5, P + 32'h0001_2000);
    // EX->EX forwarding chain and MEM->EX forwarding
    a_i(3'd0, 5'd6, 5'd0, 12'd1);
    for (int i = 0; i < 5; i++) a_r(7'd0, 3'd0, 5'd6, 5'd6, 5'd6);
    check_eq(5'd6, 32'd32);
    a_i(3'd0, 5'd7, 5'd0, 12'd3);
    emit(I_NOP);
    a_r(7'd0, 3'd0, 5'd7, 5'd7, 5'd7);
    check_eq(5'd7, 32'd6);
    // load-use
    a_lui(5'd10, 20'h00010);
    a_st(3'd2, 5'd1, 5'd10, 12'd0);
    a_ld(3'd2, 5'd11, 5'd10, 12'd0);
    a_r(7'd0, 3'd0, 5'd12, 5'd11, 5'd11);
    check_eq(5'd12, A + A);
    // byte / half
    W = 32'hF1E2_D3C4;
    a_li(5'd9, W);
    a_st(3'd2, 5'd9, 5'd10, 12'd4);
    a_ld(3'd0, 5'd11, 5'd10, 12'd4);  check_eq(5'd11, 32'hFFFF_FFC4);
    a_ld(3'd4, 5'd11, 5'd10, 12'd5);  check_eq(5'd11, 32'h0000_00D3);
    a_ld(3'd1, 5'd11, 5'd10, 12'd6);  check_eq(5'd11, 32'hFFFF_F1E2);
    a_ld(3'd5, 5'd11, 5'd10, 12'd4);  check_eq(5'd11, 32'h0000_D3C4);
    a_st(3'd0, 5'd4, 5'd10, 12'd8);
    a_st(3'd0, 5'd3, 5'd10, 12'd9);
    a_st(3'd1, 5'd2, 5'd10, 12'd10);
    a_ld(3'd2, 5'd11, 5'd10, 12'd8);  check_eq(5'd11, 32'h0F0F_FB07);
    // branches: taken skips the addi, not-taken executes it
    nt = 0;
    a_i(3'd0, 5'd12, 5'd0, 12'd0);
    a_br(3'd0, 5'd1, 5'd1, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // beq  T
    a_br(3'd0, 5'd1, 5'd2, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // beq  NT
    a_br(3'd1, 5'd1, 5'd2, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // bne  T
    a_br(3'd1, 5'd1, 5'd1, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // bne  NT
    a_br(3'd4, 5'd3, 5'd4, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // blt  T
    a_br(3'd4, 5'd4, 5'd3, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // blt  NT
    a_br(3'd5, 5'd4, 5'd3, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // bge  T
    a_br(3'd5, 5'd3, 5'd4, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // bge  NT
    a_br(3'd6, 5'd4, 5'd3, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // bltu T
    a_br(3'd6, 5'd3, 5'd4, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // bltu NT
    a_br(3'd7, 5'd3, 5'd4, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1);             // bgeu T
    a_br(3'd7, 5'd4, 5'd3, plen + 2); a_i(3'd0, 5'd12, 5'd12, 12'd1); nt = nt + 1; // bgeu NT
    check_eq(5'd12, nt);
    // jal / jalr
    L = plen;
    a_jal(5'd9, plen + 2);
    a_i(3'd0, 5'd12, 5'd12, 12'd100);
    check_eq(5'd9, L * 4 + 4);
    L = plen;
    a_auipc(5'd11, 20'd0);
    a_i(3'd0, 5'd11, 5'd11, 12'd16);
    a_jalr(5'd9, 5'd11, 12'd0);
    a_i(3'd0, 5'd12, 5'd12, 12'd100);
    check_eq(5'd9, L * 4 + 12);
    check_eq(5'd12, nt);
    prog_pass;
  endtask

  // T03 M-extension incl. divide-by-zero and overflow, back-to-back MUL/DIV
  task automatic build_t03;
    logic [31:0] pa [10];
    logic [31:0] pb [10];
    logic [31:0] e1, e2, e3;
    logic  [2:0] op;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    pa[0] = 32'd7;          pb[0] = 32'd3;
    pa[1] = 32'hFFFF_FFF9;  pb[1] = 32'd3;
    pa[2] = 32'd7;          pb[2] = 32'hFFFF_FFFD;
    pa[3] = 32'hFFFF_FFF9;  pb[3] = 32'hFFFF_FFFD;
    pa[4] = 32'h8000_0000;  pb[4] = 32'hFFFF_FFFF;
    pa[5] = 32'd5;          pb[5] = 32'd0;
    pa[6] = 32'hFFFF_FFFB;  pb[6] = 32'd0;
    pa[7] = 32'hFFFF_FFFF;  pb[7] = 32'hFFFF_FFFF;
    pa[8] = 32'h1234_5678;  pb[8] = 32'h9ABC_DEF0;
    pa[9] = 32'd0;          pb[9] = 32'd7;
    for (int j = 0; j < 10; j++) begin
      a_li(5'd1, pa[j]);
      a_li(5'd2, pb[j]);
      for (int k = 0; k < 8; k++) begin
        op = k[2:0];
        a_r(7'd1, op, 5'd5, 5'd1, 5'd2);
        check_eq(5'd5, ref_mdu(op, pa[j], pb[j]));
      end
    end
    // dependent back-to-back chain
    a_li(5'd1, 32'd1000);
    a_li(5'd2, 32'd7);
    a_r(7'd1, 3'd4, 5'd5, 5'd1, 5'd2);       // div x5 = 142
    a_r(7'd1, 3'd4, 5'd6, 5'd5, 5'd2);       // div x6 = 20
    a_r(7'd1, 3'd0, 5'd7, 5'd6, 5'd6);       // mul x7 = 400
    a_r(7'd1, 3'd6, 5'd9, 5'd7, 5'd2);       // rem x9 = 1
    e1 = 32'd1000 / 32'd7; e2 = e1 / 32'd7; e3 = e2 * e2;
    check_eq(5'd5, e1);
    check_eq(5'd6, e2);
    check_eq(5'd7, e3);
    check_eq(5'd9, e3 % 32'd7);
    prog_pass;
  endtask

  // T04 compute idle -> gate -> wake (MUL, DIV, ALU high half)
  task automatic build_t04;
    logic [31:0] A, B;
    clear_plan;
    exp_f[0] = CN_MUL; exp_f[1] = CN_DIV; exp_f[2] = CN_ADD_HI;
    exp_c[0] = CN_BANK0;
    prog_begin(8);
    pad_to(8);
    A = 32'h0001_2345; B = 32'h0000_0056;
    a_li(5'd1, A); a_li(5'd2, B);
    idle_loop(16, 8);
    a_r(7'd1, 3'd0, 5'd5, 5'd1, 5'd2);  check_eq(5'd5, A * B);
    a_r(7'd1, 3'd4, 5'd6, 5'd1, 5'd2);  check_eq(5'd6, A / B);
    a_r(7'd0, 3'd0, 5'd7, 5'd1, 5'd2);  check_eq(5'd7, A + B);
    a_r(7'd0, 3'd4, 5'd7, 5'd1, 5'd2);  check_eq(5'd7, A ^ B);
    idle_loop(16, 8);
    a_r(7'd1, 3'd3, 5'd5, 5'd1, 5'd1);  check_eq(5'd5, ref_mdu(3'd3, A, A));
    a_r(7'd1, 3'd6, 5'd6, 5'd1, 5'd2);  check_eq(5'd6, A % B);
    a_r(7'd0, 3'd7, 5'd7, 5'd1, 5'd2);  check_eq(5'd7, A & B);
    a_r(7'd0, 3'd6, 5'd7, 5'd1, 5'd2);  check_eq(5'd7, A | B);
    idle_loop(18, 8);
    a_r(7'd1, 3'd5, 5'd6, 5'd1, 5'd2);  check_eq(5'd6, A / B);
    a_r(7'd1, 3'd0, 5'd5, 5'd6, 5'd2);  check_eq(5'd5, (A / B) * B);
    prog_pass;
  endtask

  // T05 short-idle thrash: MUL / DIV separated by gaps around the thresholds
  task automatic build_t05;
    integer      gl [16];
    logic [31:0] A, B;
    logic [31:0] jj;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    gl[0] = 1;  gl[1] = 2;  gl[2] = 3;  gl[3] = 5;
    gl[4] = 8;  gl[5] = 12; gl[6] = 16; gl[7] = 20;
    gl[8] = 24; gl[9] = 2;  gl[10] = 30; gl[11] = 1;
    gl[12] = 6; gl[13] = 10; gl[14] = 14; gl[15] = 4;
    A = 32'd3; B = 32'd1000;
    a_lui(5'd8, 20'h80000);
    a_li(5'd1, A); a_li(5'd2, B);
    for (int j = 0; j < 16; j++) begin
      jj = j;
      if (jj[0] == 1'b0) a_r(7'd1, 3'd0, 5'd7, 5'd1, 5'd2);    // mul
      else               a_r(7'd1, 3'd5, 5'd9, 5'd2, 5'd1);    // divu
      gap(gl[j]);
    end
    check_eq(5'd7, A * B);
    check_eq(5'd9, B / A);
    for (int j = 0; j < 8; j++) begin
      a_r(7'd1, 3'd0, 5'd7, 5'd7, 5'd1);
      gap(gl[15 - j]);
    end
    check_eq(5'd7, A * B * 3 * 3 * 3 * 3 * 3 * 3 * 3 * 3);
    prog_pass;
  endtask

  // T06 data-memory banks: write all banks, idle, read back (retention), then
  //     work in bank 0 only and read bank 3
  task automatic build_t06;
    logic [31:0] v;
    logic [31:0] o;
    integer      lp;
    clear_plan;
    exp_f[0] = CN_BANK1;
    exp_c[0] = CN_BANK0;
    prog_begin(8);
    pad_to(8);
    a_lui(5'd10, 20'h00010);                  // x10 = 0x0001_0000 (bank 0 base)
    a_i(3'd0, 5'd11, 5'd10, 12'h7FC);         // x11 = 0x0001_07FC
    a_i(3'd0, 5'd11, 5'd11, 12'h004);         // x11 = 0x0001_0800 (bank 2 base)
    for (int k = 0; k < 4; k++) begin
      for (int j = 0; j < 4; j++) begin
        v = 32'hB000_0000 | (k << 16) | (j << 4) | 32'h5;
        a_li(5'd1, v);
        if (k < 2) begin
          o = (k * 32'h400) + j * 4;
          a_st(3'd2, 5'd1, 5'd10, o[11:0]);
        end else begin
          o = ((k - 2) * 32'h400) + j * 4;
          a_st(3'd2, 5'd1, 5'd11, o[11:0]);
        end
      end
    end
    idle_loop(16, 8);
    for (int k = 0; k < 4; k++) begin
      for (int j = 0; j < 4; j++) begin
        v = 32'hB000_0000 | (k << 16) | (j << 4) | 32'h5;
        if (k < 2) begin
          o = (k * 32'h400) + j * 4;
          a_ld(3'd2, 5'd1, 5'd10, o[11:0]);
        end else begin
          o = ((k - 2) * 32'h400) + j * 4;
          a_ld(3'd2, 5'd1, 5'd11, o[11:0]);
        end
        check_eq(5'd1, v);
      end
    end
    // bank-0 only phase
    a_lui(5'd5, 20'h00080);                   // x5 = 1<<19 -> 20 iterations
    lp = plen;
    a_ld(3'd2, 5'd1, 5'd10, 12'd0);
    a_st(3'd2, 5'd1, 5'd10, 12'd32);
    a_i(3'd5, 5'd5, 5'd5, 12'd1);
    a_br(3'd1, 5'd5, 5'd0, lp);
    emit(I_NOP);
    emit(I_NOP);
    a_ld(3'd2, 5'd1, 5'd10, 12'd32);
    check_eq(5'd1, 32'hB000_0005);
    a_ld(3'd2, 5'd1, 5'd11, 12'h40C);
    check_eq(5'd1, 32'hB003_0035);
    prog_pass;
  endtask

  // T07 register-file bank HI retention
  task automatic build_t07;
    logic [31:0] v;
    logic [31:0] jj;
    clear_plan;
    exp_f[0] = CN_RFHI;
    exp_c[0] = CN_RFHI;
    prog_begin(8);
    pad_to(8);
    for (int j = 16; j < 28; j++) begin
      jj = j;
      v  = 32'hA500_0000 | (j << 16) | (j * 3);
      a_li(jj[4:0], v);
    end
    idle_loop(16, 8);
    for (int j = 16; j < 28; j++) begin
      jj = j;
      v  = 32'hA500_0000 | (j << 16) | (j * 3);
      check_eq(jj[4:0], v);
    end
    a_r(7'd0, 3'd0, 5'd16, 5'd16, 5'd17);
    v = (32'hA500_0000 | (32'd16 << 16) | 32'd48) + (32'hA500_0000 | (32'd17 << 16) | 32'd51);
    idle_loop(16, 16);
    check_eq(5'd16, v);
    prog_pass;
  endtask

  // T08 WFI with polling (MIE = 0), batching threshold, long sleep
  task automatic build_t08;
    clear_plan;
    exp_f[0] = CN_MUL; exp_f[1] = CN_BANK0;
    exp_c[0] = CN_CORE;
    add_event(40,  1, 8'h11);
    add_event(60,  2, 8'h22);
    add_event(30,  3, 8'h33);
    add_event(300, 0, 8'h44);
    prog_begin(8);
    pad_to(8);
    a_lui(5'd10, 20'h00020);                  // EVQ base
    a_li(5'd1, 32'h800);
    a_csr(3'd1, 5'd0, 12'h304, 5'd1);         // mie.MEIE = 1
    a_li(5'd2, 32'd2);
    a_st(3'd2, 5'd2, 5'd10, 12'd8);           // threshold 2
    emit(I_WFI);
    a_ld(3'd2, 5'd3, 5'd10, 12'd0);  check_eq(5'd3, 32'd2);
    a_ld(3'd2, 5'd4, 5'd10, 12'd4);  check_eq(5'd4, 32'h8000_0111);
    a_ld(3'd2, 5'd4, 5'd10, 12'd4);  check_eq(5'd4, 32'h8000_0222);
    a_ld(3'd2, 5'd3, 5'd10, 12'd0);  check_eq(5'd3, 32'd0);
    a_li(5'd2, 32'd1);
    a_st(3'd2, 5'd2, 5'd10, 12'd8);           // threshold 1
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd10, 12'd4);  check_eq(5'd4, 32'h8000_0333);
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd10, 12'd4);  check_eq(5'd4, 32'h8000_0044);
    prog_pass;
  endtask

  // T09 WFI with interrupt (MIE = 1): trap, handler pops the event, mret
  task automatic build_t09;
    clear_plan;
    exp_f[0] = CN_MUL;
    exp_c[0] = CN_CORE;
    add_event(25,  1, 8'hA1);
    add_event(50,  2, 8'hB2);
    add_event(200, 3, 8'hC3);
    prog_begin(32);
    // handler at word 4 (mtvec = 16)
    a_csr(3'd2, 5'd11, 12'h342, 5'd0);        // csrr x11, mcause
    a_st(3'd2, 5'd11, 5'd9, 12'd0);
    a_ld(3'd2, 5'd12, 5'd10, 12'd4);          // pop
    a_st(3'd2, 5'd12, 5'd9, 12'd4);
    a_i(3'd0, 5'd9, 5'd9, 12'd8);
    a_i(3'd0, 5'd7, 5'd7, 12'd1);
    emit(I_MRET);
    pad_to(32);
    a_lui(5'd10, 20'h00020);
    a_lui(5'd9, 20'h00010);
    a_i(3'd0, 5'd9, 5'd9, 12'h100);
    a_i(3'd0, 5'd7, 5'd0, 12'd0);
    a_i(3'd0, 5'd6, 5'd0, 12'd0);
    a_li(5'd1, 32'd16);
    a_csr(3'd1, 5'd0, 12'h305, 5'd1);         // mtvec
    a_li(5'd1, 32'h800);
    a_csr(3'd1, 5'd0, 12'h304, 5'd1);         // mie.MEIE
    a_li(5'd2, 32'd1);
    a_st(3'd2, 5'd2, 5'd10, 12'd8);           // threshold 1
    a_csr(3'd6, 5'd0, 12'h300, 5'd8);         // csrsi mstatus, MIE
    emit(I_WFI); a_i(3'd0, 5'd6, 5'd6, 12'd1);
    emit(I_WFI); a_i(3'd0, 5'd6, 5'd6, 12'd1);
    emit(I_WFI); a_i(3'd0, 5'd6, 5'd6, 12'd1);
    a_csr(3'd7, 5'd0, 12'h300, 5'd8);         // csrci mstatus, MIE
    check_eq(5'd7, 32'd3);
    check_eq(5'd6, 32'd3);
    a_lui(5'd9, 20'h00010);
    a_ld(3'd2, 5'd1, 5'd9, 12'h100); check_eq(5'd1, 32'h8000_000B);
    a_ld(3'd2, 5'd1, 5'd9, 12'h104); check_eq(5'd1, 32'h8000_01A1);
    a_ld(3'd2, 5'd1, 5'd9, 12'h10C); check_eq(5'd1, 32'h8000_02B2);
    a_ld(3'd2, 5'd1, 5'd9, 12'h110); check_eq(5'd1, 32'h8000_000B);
    a_ld(3'd2, 5'd1, 5'd9, 12'h114); check_eq(5'd1, 32'h8000_03C3);
    prog_pass;
  endtask

  // T10 synchronous traps (ecall, illegal, ebreak) around gated units
  task automatic build_t10;
    clear_plan;
    prog_begin(32);
    // handler: log mcause, mepc += 4, count
    a_csr(3'd2, 5'd11, 12'h342, 5'd0);
    a_st(3'd2, 5'd11, 5'd9, 12'd0);
    a_i(3'd0, 5'd9, 5'd9, 12'd4);
    a_csr(3'd2, 5'd12, 12'h341, 5'd0);
    a_i(3'd0, 5'd12, 5'd12, 12'd4);
    a_csr(3'd1, 5'd0, 12'h341, 5'd12);
    a_i(3'd0, 5'd7, 5'd7, 12'd1);
    emit(I_MRET);
    pad_to(32);
    a_lui(5'd9, 20'h00010);
    a_i(3'd0, 5'd9, 5'd9, 12'h200);
    a_i(3'd0, 5'd7, 5'd0, 12'd0);
    a_li(5'd1, 32'd16);
    a_csr(3'd1, 5'd0, 12'h305, 5'd1);
    a_li(5'd1, 32'd6);
    a_li(5'd2, 32'd7);
    a_r(7'd1, 3'd0, 5'd5, 5'd1, 5'd2);       // mul 42
    emit(I_ECALL);
    check_eq(5'd5, 32'd42);
    emit(32'hFFFF_FFFF);                     // illegal
    a_r(7'd1, 3'd4, 5'd5, 5'd5, 5'd2);       // div 6
    check_eq(5'd5, 32'd6);
    emit(I_EBREAK);
    idle_loop(16, 8);
    emit(I_ECALL);
    check_eq(5'd7, 32'd4);
    a_lui(5'd9, 20'h00010);
    a_ld(3'd2, 5'd1, 5'd9, 12'h200); check_eq(5'd1, 32'd11);
    a_ld(3'd2, 5'd1, 5'd9, 12'h204); check_eq(5'd1, 32'd2);
    a_ld(3'd2, 5'd1, 5'd9, 12'h208); check_eq(5'd1, 32'd3);
    a_ld(3'd2, 5'd1, 5'd9, 12'h20C); check_eq(5'd1, 32'd11);
    prog_pass;
  endtask

  // prelude for T10: endless idle program used to reset the DUT while gated
  task automatic build_idle_forever;
    integer top;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    top = plen;
    idle_loop(16, 8);
    a_jal(5'd0, top);
    emit(I_NOP);
    emit(I_NOP);
  endtask

  // T11 constrained-random program (REF vs DUT lock-step is the checker)
  task automatic build_t11;
    logic  [4:0] rs [21];
    logic [31:0] rnd;
    logic [31:0] kk;
    integer      n, sel, lp;
    logic  [4:0] rd_, r1_, r2_;
    logic  [2:0] f3_;
    logic [11:0] off;
    clear_plan;
    prog_begin(8);
    pad_to(8);
    rs[0] = 5'd1;  rs[1] = 5'd2;  rs[2] = 5'd3;  rs[3] = 5'd4;  rs[4] = 5'd6;
    rs[5] = 5'd7;  rs[6] = 5'd9;  rs[7] = 5'd12;
    for (int k = 0; k < 12; k++) begin
      kk = k;
      rs[8 + k] = 5'd16 + kk[4:0];
    end
    rs[20] = 5'd0;
    a_lui(5'd8, 20'h80000);
    a_lui(5'd10, 20'h00010);
    a_i(3'd0, 5'd11, 5'd10, 12'h7FC);
    a_i(3'd0, 5'd11, 5'd11, 12'h004);
    for (int k = 0; k < 20; k++) begin
      rnd = $random(seed);
      a_li(rs[k], rnd);
    end
    n = 0;
    while ((n < 300) && (plen < 940)) begin
      sel = {$random(seed)} % 100;
      rd_ = rs[{$random(seed)} % 20];
      r1_ = rs[{$random(seed)} % 21];
      r2_ = rs[{$random(seed)} % 21];
      rnd = $random(seed);
      if (sel < 30) begin
        case ({$random(seed)} % 10)
          0: a_r(7'd0,  3'd0, rd_, r1_, r2_);
          1: a_r(7'h20, 3'd0, rd_, r1_, r2_);
          2: a_r(7'd0,  3'd1, rd_, r1_, r2_);
          3: a_r(7'd0,  3'd2, rd_, r1_, r2_);
          4: a_r(7'd0,  3'd3, rd_, r1_, r2_);
          5: a_r(7'd0,  3'd4, rd_, r1_, r2_);
          6: a_r(7'd0,  3'd5, rd_, r1_, r2_);
          7: a_r(7'h20, 3'd5, rd_, r1_, r2_);
          8: a_r(7'd0,  3'd6, rd_, r1_, r2_);
          default: a_r(7'd0, 3'd7, rd_, r1_, r2_);
        endcase
      end else if (sel < 50) begin
        case ({$random(seed)} % 9)
          0: a_i(3'd0, rd_, r1_, rnd[11:0]);
          1: a_i(3'd2, rd_, r1_, rnd[11:0]);
          2: a_i(3'd3, rd_, r1_, rnd[11:0]);
          3: a_i(3'd4, rd_, r1_, rnd[11:0]);
          4: a_i(3'd6, rd_, r1_, rnd[11:0]);
          5: a_i(3'd7, rd_, r1_, rnd[11:0]);
          6: a_i(3'd1, rd_, r1_, {7'd0, rnd[4:0]});
          7: a_i(3'd5, rd_, r1_, {7'd0, rnd[4:0]});
          default: a_i(3'd5, rd_, r1_, {7'h20, rnd[4:0]});
        endcase
      end else if (sel < 60) begin
        a_r(7'd1, rnd[2:0], rd_, r1_, r2_);
      end else if (sel < 78) begin
        off = {1'b0, rnd[10:2], 2'b00};
        case ({$random(seed)} % 8)
          0: a_ld(3'd2, rd_, (rnd[20] ? 5'd11 : 5'd10), off);
          1: a_st(3'd2, r2_, (rnd[20] ? 5'd11 : 5'd10), off);
          2: a_ld(3'd0, rd_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22:21]});
          3: a_ld(3'd4, rd_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22:21]});
          4: a_ld(3'd1, rd_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22], 1'b0});
          5: a_ld(3'd5, rd_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22], 1'b0});
          6: a_st(3'd0, r2_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22:21]});
          default: a_st(3'd1, r2_, (rnd[20] ? 5'd11 : 5'd10), off | {10'd0, rnd[22], 1'b0});
        endcase
      end else if (sel < 88) begin
        gap(3 + ({$random(seed)} % 18));
      end else if (sel < 96) begin
        case ({$random(seed)} % 6)
          0: f3_ = 3'd0;
          1: f3_ = 3'd1;
          2: f3_ = 3'd4;
          3: f3_ = 3'd5;
          4: f3_ = 3'd6;
          default: f3_ = 3'd7;
        endcase
        lp = plen + 3;
        a_br(f3_, r1_, r2_, lp);
        a_r(7'd0, 3'd0, rd_, r1_, r2_);
        a_r(7'd0, 3'd4, rd_, rd_, r2_);
      end else begin
        if (rnd[0]) a_lui(rd_, rnd[31:12]);
        else        a_auipc(rd_, rnd[31:12]);
      end
      n = n + 1;
    end
    prog_pass;
  endtask

  //=========================================================== ML / CG+PG tests (MODE 3 / 4)
  // common: x8 = 0x8000_0000 (gap), x10 = bank0, x11 = bank1, x12 = event queue
  task automatic ml_setup;
    a_lui(5'd8, 20'h80000);
    a_lui(5'd10, 20'h00010);
    a_i(3'd0, 5'd11, 5'd10, 12'h400);
    a_lui(5'd12, 20'h00020);
  endtask

  // enable MEIE (no trap: polling WFI as in T08) and set batching threshold 1
  task automatic ml_wfi_setup;
    a_li(5'd3, 32'h800);
    a_csr(3'd1, 5'd0, 12'h304, 5'd3);
    a_i(3'd0, 5'd4, 5'd0, 12'd1);
    a_st(3'd2, 5'd4, 5'd12, 12'd8);
  endtask

  // T12 confident wrong prediction: ml_force = 1 makes every idle power
  //     domain request a confident power-off. The shell must keep the core
  //     correct, wake within bound, and count the wrong gates as mispredicts.
  task automatic build_t12;
    logic [31:0] o;
    clear_plan;
    t_force    = 2'd1;
    exp_pg_req = 1'b1;
    exp_f[0] = CN_MUL; exp_f[1] = CN_BANK1;
    exp_c[0] = CN_BANK0; exp_c[1] = CN_CORE;
    add_event(100, 1, 8'h5A);
    prog_begin(8);
    pad_to(8);
    ml_setup;
    a_li(5'd1, 32'd7);
    a_li(5'd2, 32'd3);
    a_i(3'd0, 5'd9, 5'd0, 12'd0);
    // note: gap / idle_loop use x5 and x6 as scratch registers
    for (int j = 0; j < 6; j++) begin
      a_r(7'd1, 3'd0, 5'd7, 5'd1, 5'd2);          // mul x7 = 21
      gap(2 + j);
      a_r(7'd1, 3'd4, 5'd6, 5'd7, 5'd2);          // div x6 = 7
      gap(3);
      a_r(7'd0, 3'd0, 5'd9, 5'd9, 5'd6);          // x9 += 7
      o = j * 4;
      a_st(3'd2, 5'd9, 5'd11, o[11:0]);
      gap(4);
    end
    check_eq(5'd9, 32'd42);
    a_ld(3'd2, 5'd7, 5'd11, 12'd20); check_eq(5'd7, 32'd42);
    a_ld(3'd2, 5'd7, 5'd11, 12'd0);  check_eq(5'd7, 32'd7);
    ml_wfi_setup;
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);  check_eq(5'd4, 32'h8000_015A);
    prog_pass;
  endtask

  // T13 low confidence: ml_force = 2 sets the model confidence to 0. The shell
  //     must refuse every power-gating request (no PG entry), clock gating
  //     must still work, the program has long idles where PG would pay off.
  task automatic build_t13;
    logic [31:0] A, B;
    clear_plan;
    t_force = 2'd2;
    exp_f[0] = CN_MUL; exp_f[1] = CN_BANK1;
    exp_c[0] = CN_BANK0; exp_c[1] = CN_CORE;
    add_event(150, 2, 8'h3C);
    prog_begin(8);
    pad_to(8);
    ml_setup;
    A = 32'h0000_1234; B = 32'h0000_0056;
    a_li(5'd1, A);
    a_li(5'd2, B);
    a_st(3'd2, 5'd1, 5'd11, 12'd0);
    a_r(7'd1, 3'd0, 5'd5, 5'd1, 5'd2);  check_eq(5'd5, A * B);
    idle_loop(16, 8);
    a_r(7'd1, 3'd0, 5'd6, 5'd1, 5'd2);  check_eq(5'd6, A * B);
    a_ld(3'd2, 5'd7, 5'd11, 12'd0);     check_eq(5'd7, A);
    ml_wfi_setup;
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);     check_eq(5'd4, 32'h8000_023C);
    prog_pass;
  endtask

  // T14 sleep classes: three WFI sleeps (short 10, medium 60, long 400 cycles)
  //     with data in three banks; the data must survive every sleep. The idle
  //     table shows which sleeps the policy powered down.
  task automatic build_t14;
    clear_plan;
    exp_f[0] = CN_BANK1;
    exp_c[0] = CN_CORE;
    add_event(10,  0, 8'h11);
    add_event(60,  1, 8'h22);
    add_event(400, 2, 8'h33);
    prog_begin(8);
    pad_to(8);
    ml_setup;
    a_lui(5'd9, 20'h00010);
    a_i(3'd0, 5'd9, 5'd9, 12'h7FC);
    a_i(3'd0, 5'd9, 5'd9, 12'h004);                // x9 = bank2 base
    a_li(5'd1, 32'hA0A0_0001); a_st(3'd2, 5'd1, 5'd10, 12'd0);
    a_li(5'd1, 32'hB1B1_0002); a_st(3'd2, 5'd1, 5'd11, 12'd0);
    a_li(5'd1, 32'hC2C2_0003); a_st(3'd2, 5'd1, 5'd9,  12'd0);
    ml_wfi_setup;
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);  check_eq(5'd4, 32'h8000_0011);
    a_ld(3'd2, 5'd1, 5'd10, 12'd0);  check_eq(5'd1, 32'hA0A0_0001);
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);  check_eq(5'd4, 32'h8000_0122);
    a_ld(3'd2, 5'd1, 5'd11, 12'd0);  check_eq(5'd1, 32'hB1B1_0002);
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);  check_eq(5'd4, 32'h8000_0233);
    a_ld(3'd2, 5'd1, 5'd9,  12'd0);  check_eq(5'd1, 32'hC2C2_0003);
    a_ld(3'd2, 5'd1, 5'd10, 12'd0);  check_eq(5'd1, 32'hA0A0_0001);
    a_ld(3'd2, 5'd1, 5'd11, 12'd0);  check_eq(5'd1, 32'hB1B1_0002);
    prog_pass;
  endtask

  // T15 periodic pattern: 12 x (two dependent MULs, then ~60 idle cycles).
  //     The idle length repeats, which the history features can learn.
  task automatic build_t15;
    integer lp;
    clear_plan;
    exp_f[0] = CN_MUL;
    exp_c[0] = CN_BANK0;
    prog_begin(8);
    pad_to(8);
    ml_setup;
    a_li(5'd1, 32'd3);
    a_li(5'd2, 32'd5);
    a_li(5'd7, 32'd1);
    a_li(5'd3, 32'd12);
    lp = plen;
    a_r(7'd1, 3'd0, 5'd7, 5'd7, 5'd1);             // x7 *= 3
    a_r(7'd1, 3'd0, 5'd9, 5'd7, 5'd2);             // x9 = x7 * 5
    gap(14);
    a_i(3'd0, 5'd3, 5'd3, 12'hFFF);                // x3 -= 1
    a_br(3'd1, 5'd3, 5'd0, lp);
    emit(I_NOP);
    emit(I_NOP);
    check_eq(5'd7, 32'd531441);
    check_eq(5'd9, 32'd2657205);
    prog_pass;
  endtask

  // T16 CG -> PG escalation: a long MUL idle (fine) and a long WFI sleep
  //     (coarse). Reactive CG+PG first clock-gates (8 cycles) then powers off
  //     (16 cycles); MODE 3 must show at least one escalation on the MUL net.
  task automatic build_t16;
    clear_plan;
    exp_f[0] = CN_MUL;
    exp_c[0] = CN_CORE;
    add_event(300, 3, 8'h77);
    prog_begin(8);
    pad_to(8);
    ml_setup;
    a_li(5'd1, 32'd1234);
    a_li(5'd2, 32'd77);
    a_r(7'd1, 3'd0, 5'd9, 5'd1, 5'd2);  check_eq(5'd9, 32'd95018);
    idle_loop(16, 8);                                // uses x5, x6
    a_r(7'd1, 3'd0, 5'd7, 5'd9, 5'd2);  check_eq(5'd7, 32'd7316386);
    ml_wfi_setup;
    emit(I_WFI);
    a_ld(3'd2, 5'd4, 5'd12, 12'd4);     check_eq(5'd4, 32'h8000_0377);
    a_r(7'd1, 3'd0, 5'd6, 5'd1, 5'd1);  check_eq(5'd6, 32'd1522756);
    prog_pass;
  endtask

  //=========================================================== dispatcher
  task automatic build(input int t);
    case (t)
      1:       build_t01;
      2:       build_t02;
      3:       build_t03;
      4:       build_t04;
      5:       build_t05;
      6:       build_t06;
      7:       build_t07;
      8:       build_t08;
      9:       build_t09;
      10:      build_t10;
      11:      build_t11;
      12:      build_t12;
      13:      build_t13;
      14:      build_t14;
      15:      build_t15;
      default: build_t16;
    endcase
  endtask
endmodule : fido_tb_programs

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> tb/fido_tb_event_src.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_event_src.sv
// Module    : fido_tb_event_src
// Content   : peripheral event source (UART / SPI / timer / GPIO stand-in) for
//             ONE core. Events of the plan are delivered relative to that
//             core's own WFI sleep: event i fires ev_dly[i] cycles into a
//             sleep. REF and DUT therefore see the same event sequence and
//             retire the same instruction stream, whatever the gating does to
//             their timing. Drives on the negative clock edge.
// Hierarchy : tb_<cfg> > u_env > u_ev_ref / u_ev_dut
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module fido_tb_event_src (
  input  wire           clk,
  input  wire           rst_n,
  input  wire           wfi,          // the core is asleep (pipeline drained)
  input  wire    [31:0] ev_n,         // number of events in the plan
  input  wire  [1023:0] ev_dly_v,
  input  wire    [63:0] ev_src_v,
  input  wire   [255:0] ev_dat_v,
  output logic    [3:0] ev_valid,
  output logic   [31:0] ev_data
);
  int idx = 0;    // next event of the plan
  int cnt = 0;    // cycles into the present sleep

  always @(negedge clk) begin
    if (!rst_n) begin
      idx      <= 0;
      cnt      <= 0;
      ev_valid <= 4'd0;
      ev_data  <= 32'd0;
    end else begin
      ev_valid <= 4'd0;
      if (wfi) begin
        cnt <= cnt + 1;
        if ((idx < ev_n) && (cnt == ev_dly_v[idx*32 +: 32])) begin
          ev_valid[ev_src_v[idx*2 +: 2]]          <= 1'b1;
          ev_data[ev_src_v[idx*2 +: 2]*8 +: 8]    <= ev_dat_v[idx*8 +: 8];
          idx <= idx + 1;
        end
      end else begin
        cnt <= 0;
      end
    end
  end
endmodule : fido_tb_event_src

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> tb/fido_tb_scoreboard.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_scoreboard.sv
// Module    : fido_tb_scoreboard
// Content   : lock-step retirement scoreboard. Every REF retirement is pushed
//             into a FIFO, every DUT retirement is popped and compared
//             (pc, insn, rd, wdata, store address / data / strobe; 4-state
//             compare, so X from a wrongly powered-down domain is caught).
//             A store to TOHOST ends the program of that core. Also counts
//             the cycles of each core (overhead = DUT vs REF cycles).
// Hierarchy : tb_<cfg> > u_env > u_sb
// Access    : the environment calls clear() and reads the counters.
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module fido_tb_scoreboard
  import fido_tb_pkg::*;
(
  input  wire        clk,
  input  wire        rst_n,
  input  wire        en,            // sampling enabled (set / cleared on posedge)
  input  wire        verbose,
  // REF retirement
  input  wire        ref_valid,
  input  wire [31:0] ref_pc,
  input  wire [31:0] ref_insn,
  input  wire  [4:0] ref_rd,
  input  wire [31:0] ref_wdata,
  input  wire        ref_mem_we,
  input  wire [31:0] ref_mem_addr,
  input  wire [31:0] ref_mem_wdata,
  input  wire  [3:0] ref_mem_strb,
  // DUT retirement
  input  wire        dut_valid,
  input  wire [31:0] dut_pc,
  input  wire [31:0] dut_insn,
  input  wire  [4:0] dut_rd,
  input  wire [31:0] dut_wdata,
  input  wire        dut_mem_we,
  input  wire [31:0] dut_mem_addr,
  input  wire [31:0] dut_mem_wdata,
  input  wire  [3:0] dut_mem_strb
);
  //=========================================================== FIFO
  logic [31:0] f_pc    [FIFO_D];
  logic [31:0] f_insn  [FIFO_D];
  logic  [4:0] f_rd    [FIFO_D];
  logic [31:0] f_wdata [FIFO_D];
  logic        f_mwe   [FIFO_D];
  logic [31:0] f_maddr [FIFO_D];
  logic [31:0] f_mdata [FIFO_D];
  logic  [3:0] f_mstrb [FIFO_D];
  int          f_wp  = 0;
  int          f_rp  = 0;
  int          f_cnt = 0;

  //=========================================================== results (read by the environment)
  logic        ref_done = 1'b0;
  logic        dut_done = 1'b0;
  logic [31:0] ref_code = 32'd0;
  logic [31:0] dut_code = 32'd0;
  int          ref_ret  = 0;
  int          dut_ret  = 0;
  int          sb_err   = 0;
  int          ref_cyc  = 0;
  int          dut_cyc  = 0;
  int          run_cyc  = 0;

  task automatic clear;
    f_wp     = 0;
    f_rp     = 0;
    f_cnt    = 0;
    ref_done = 1'b0;
    dut_done = 1'b0;
    ref_code = 32'd0;
    dut_code = 32'd0;
    ref_ret  = 0;
    dut_ret  = 0;
    sb_err   = 0;
    ref_cyc  = 0;
    dut_cyc  = 0;
    run_cyc  = 0;
  endtask

  //=========================================================== sampling (negative edge)
  always @(negedge clk) begin
    if (rst_n && en) begin
      run_cyc = run_cyc + 1;
      if (!ref_done) ref_cyc = ref_cyc + 1;
      if (!dut_done) dut_cyc = dut_cyc + 1;
      // REF retire -> push
      if (ref_valid && !ref_done) begin
        if (f_cnt >= FIFO_D) begin
          sb_err = sb_err + 1;
          $display("[%0t] SCOREBOARD: REF ahead by more than %0d retirements", $time, FIFO_D);
        end else begin
          f_pc[f_wp]    = ref_pc;
          f_insn[f_wp]  = ref_insn;
          f_rd[f_wp]    = ref_rd;
          f_wdata[f_wp] = ref_wdata;
          f_mwe[f_wp]   = ref_mem_we;
          f_maddr[f_wp] = ref_mem_addr;
          f_mdata[f_wp] = ref_mem_wdata;
          f_mstrb[f_wp] = ref_mem_strb;
          f_wp  = (f_wp + 1) % FIFO_D;
          f_cnt = f_cnt + 1;
        end
        ref_ret = ref_ret + 1;
        if (ref_mem_we && (ref_mem_addr == 32'h0003_0000)) begin
          ref_done = 1'b1;
          ref_code = ref_mem_wdata;
        end
      end
      // DUT retire -> pop and compare
      if (dut_valid && !dut_done) begin
        if (f_cnt == 0) begin
          sb_err = sb_err + 1;
          if (verbose || (sb_err <= 5))
            $display("[%0t] SCOREBOARD: DUT retired pc=%08h with no REF entry", $time, dut_pc);
        end else begin
          if ((dut_pc !== f_pc[f_rp]) || (dut_insn !== f_insn[f_rp]) ||
              (dut_rd !== f_rd[f_rp]) || (dut_wdata !== f_wdata[f_rp]) ||
              (dut_mem_we !== f_mwe[f_rp]) || (dut_mem_addr !== f_maddr[f_rp]) ||
              (dut_mem_wdata !== f_mdata[f_rp]) || (dut_mem_strb !== f_mstrb[f_rp])) begin
            sb_err = sb_err + 1;
            if (verbose || (sb_err <= 5)) begin
              $display("[%0t] SCOREBOARD MISMATCH #%0d (retirement %0d)", $time, sb_err, dut_ret);
              $display("    REF pc=%08h insn=%08h rd=x%0d wdata=%08h st=%0b addr=%08h data=%08h strb=%b",
                       f_pc[f_rp], f_insn[f_rp], f_rd[f_rp], f_wdata[f_rp], f_mwe[f_rp],
                       f_maddr[f_rp], f_mdata[f_rp], f_mstrb[f_rp]);
              $display("    DUT pc=%08h insn=%08h rd=x%0d wdata=%08h st=%0b addr=%08h data=%08h strb=%b",
                       dut_pc, dut_insn, dut_rd, dut_wdata, dut_mem_we, dut_mem_addr,
                       dut_mem_wdata, dut_mem_strb);
            end
          end
          f_rp  = (f_rp + 1) % FIFO_D;
          f_cnt = f_cnt - 1;
        end
        dut_ret = dut_ret + 1;
        if (dut_mem_we && (dut_mem_addr == 32'h0003_0000)) begin
          dut_done = 1'b1;
          dut_code = dut_mem_wdata;
        end
      end
    end
  end
endmodule : fido_tb_scoreboard

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> tb/fido_tb_monitor.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_monitor.sv
// Module    : fido_tb_monitor
// Content   : power-management monitor + protocol checker of the DUT
//   monitor : per domain slot - gating entries, wakes, gated cycles,
//             mispredicts, maximum wake latency; gating stall cycles
//   checker : safety-shell protocol rules (simulation form of the SVA list)
//             A1 no clock enable while PG_RET / PG_OFF / WAKING      (SH-1)
//             A2 isolation asserted before the switch opens          (SH-2)
//             A3 retention saved before the switch opens (live)      (SH-3)
//             A4 isolation released only after restore, power + ack  (SH-4)
//             A5 clock never gated while the unit writes             (SEC stand-in)
//             A6 wake completes within WAKE_PG + 8 cycles            (SH-5)
//             A7 no gating accepted during the trap window           (PM-3)
//             A8 no X/Z on DUT control outputs                       (UP-1)
//   MODE 3/4: every idle period of every power domain is scored against
//             BE_LBL (TP gated+long, FP gated+short, FN missed-long,
//             TN kept-short); CG -> PG escalations on the MUL net counted
//   +MLTRACE: one CSV line per cycle and power domain (training data)
// Hierarchy : tb_<cfg> > u_env > u_mon
// Access    : the environment calls clear(), trace_open(), trace_close() and
//             reads / updates the counters.
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module fido_tb_monitor
  import fido_pkg::*;
  import fido_tb_pkg::*;
#(
  parameter int MODE    = 0,
  parameter int GRAIN   = 0,
  parameter int WAKE_PG = 4
) (
  input  wire          clk,
  input  wire          rst_n,
  input  wire          en,            // sampling enabled (set / cleared on posedge)
  input  wire          verbose,
  input  wire          mltrace,
  input  wire          dut_valid,
  input  wire          dut_wfi,
  input  wire          dut_trap_win,
  input  wire          dut_pg_stall,
  input  wire  [95:0]  pm_state_bus,
  input  wire  [31:0]  dom_clk_en,
  input  wire  [31:0]  dom_iso,
  input  wire  [31:0]  dom_ret,
  input  wire  [31:0]  dom_pwr,
  input  wire  [31:0]  dom_ack,
  input  wire  [31:0]  dom_busy,
  input  wire  [31:0]  dom_ready,
  input  wire  [31:0]  dom_mispred,
  input  wire [255:0]  ml_feat
);
  localparam int NCG      = (GRAIN == 0) ? NCG_FINE : NCG_COARSE;
  localparam int NPG      = (GRAIN == 0) ? NPG_FINE : NPG_COARSE;
  localparam int ND       = (MODE == MODE_CG) ? NCG : (MODE == MODE_PG) ? NPG :
                            (MODE >= MODE_CGPG) ? (NCG + NPG) : 0;
  localparam int WAKE_MAX = WAKE_PG + 8;

  //=========================================================== statistics (read by the environment)
  int          m_entry [32];
  int          m_wake  [32];
  int          m_gcyc  [32];
  int          m_mis   [32];
  int          m_lat   [32];
  int          m_maxl  [32];
  int          m_stall = 0;
  int          cm_tp   [8];
  int          cm_fp   [8];
  int          cm_fn   [8];
  int          cm_tn   [8];
  int          m_esc   = 0;
  int          chk_err = 0;

  //=========================================================== history
  logic  [2:0] p_st    [32];
  logic        p_pwr   [32];
  logic        p_iso   [32];
  logic        p_ret   [32];
  logic        p_ack   [32];
  logic        p_trap  = 1'b0;
  int          w_cnt   [32];
  logic        w_flag  [32];
  logic        q_idle  [8];
  logic        q_gated [8];
  int          q_len   [8];

  //=========================================================== ML trace
  integer      tr_fd  = 0;
  int          tr_cyc = 0;

  task automatic clear;
    for (int i = 0; i < 32; i++) begin
      m_entry[i] = 0; m_wake[i] = 0; m_gcyc[i] = 0; m_mis[i] = 0;
      m_lat[i]   = 0; m_maxl[i] = 0; w_cnt[i]  = 0; w_flag[i] = 1'b0;
      p_st[i]  = PM_ON; p_pwr[i] = 1'b1; p_iso[i] = 1'b0; p_ret[i] = 1'b0; p_ack[i] = 1'b1;
    end
    for (int i = 0; i < 8; i++) begin
      q_idle[i] = 1'b0; q_gated[i] = 1'b0; q_len[i] = 0;
      cm_tp[i]  = 0;    cm_fp[i]   = 0;    cm_fn[i] = 0; cm_tn[i] = 0;
    end
    m_esc   = 0;
    p_trap  = 1'b0;
    m_stall = 0;
    chk_err = 0;
    tr_cyc  = 0;
  endtask

  task automatic chk_fail(input int d, input string msg);
    chk_err = chk_err + 1;
    if (verbose || (chk_err <= 10))
      $display("[%0t] CHECKER %0s: %0s", $time, dname(MODE, GRAIN, d), msg);
  endtask

  task automatic trace_open(input int t);
    string tr_name;
    tr_name = $sformatf("ml_trace_T%02d.csv", t);
    tr_fd   = $fopen(tr_name, "w");
    if (tr_fd != 0)
      $fdisplay(tr_fd, "cycle,slot,busy,idle,h1,h2,occ,wfi,evq,live");
  endtask

  task automatic trace_close;
    if (tr_fd != 0) begin
      $fclose(tr_fd);
      tr_fd = 0;
    end
  endtask

  //=========================================================== monitor + checker (negative edge)
  logic [2:0] st_now;

  always @(negedge clk) begin
    if (rst_n && en && (MODE != 0)) begin
      if (dut_pg_stall) m_stall = m_stall + 1;
      for (int dd = 0; dd < ND; dd++) begin
        st_now = pm_state_bus[3*dd +: 3];
        //---------------- monitor
        if ((p_st[dd] == PM_ON) && (st_now != PM_ON)) m_entry[dd] = m_entry[dd] + 1;
        if ((p_st[dd] != PM_ON) && (st_now == PM_ON)) m_wake[dd]  = m_wake[dd] + 1;
        if (st_now != PM_ON) m_gcyc[dd] = m_gcyc[dd] + 1;
        if (dom_mispred[dd]) m_mis[dd] = m_mis[dd] + 1;
        if ((st_now >= PM_PG_RET) && dom_busy[dd]) begin
          m_lat[dd] = m_lat[dd] + 1;
        end else if (st_now == PM_ON) begin
          if (m_lat[dd] > m_maxl[dd]) m_maxl[dd] = m_lat[dd];
          m_lat[dd] = 0;
        end
        //---------------- checker
        if ((st_now >= PM_PG_RET) && dom_clk_en[dd])
          chk_fail(dd, "A1 clock enabled while PG/WAKING");
        if (p_pwr[dd] && !dom_pwr[dd] && !p_iso[dd])
          chk_fail(dd, "A2 switch opened before isolation");
        if (p_pwr[dd] && !dom_pwr[dd] && (st_now == PM_PG_RET) && !p_ret[dd])
          chk_fail(dd, "A3 switch opened before retention save");
        if (p_iso[dd] && !dom_iso[dd] && (p_ret[dd] || !p_ack[dd] || !p_pwr[dd]))
          chk_fail(dd, "A4 isolation released too early");
        if (is_cg_slot(MODE, GRAIN, dd) && dom_busy[dd] && !dom_clk_en[dd])
          chk_fail(dd, "A5 clock gated while unit writes");
        if ((st_now >= PM_PG_RET) && dom_busy[dd]) begin
          w_cnt[dd] = w_cnt[dd] + 1;
          if ((w_cnt[dd] > WAKE_MAX) && !w_flag[dd]) begin
            w_flag[dd] = 1'b1;
            chk_fail(dd, "A6 wake-up exceeded bound");
          end
        end else if (st_now <= PM_CG) begin
          w_cnt[dd] = 0; w_flag[dd] = 1'b0;
        end
        if ((p_st[dd] == PM_ON) && (st_now != PM_ON) && p_trap)
          chk_fail(dd, "A7 gated during trap window");
        // CG -> PG escalation on the MUL clock net (MODE 3 / 4): the power
        // domain switches off while the clock domain is already clock-gated
        if ((MODE >= 3) && (dd == cn2pg(GRAIN, CN_MUL)) && (p_st[dd] == PM_ON) &&
            (st_now >= PM_PG_RET) && (pm_state_bus[3*cn2cg(GRAIN, CN_MUL) +: 3] == PM_CG))
          m_esc = m_esc + 1;
        //---------------- history
        p_st[dd]  = st_now;
        p_pwr[dd] = dom_pwr[dd];
        p_iso[dd] = dom_iso[dd];
        p_ret[dd] = dom_ret[dd];
        p_ack[dd] = dom_ack[dd];
      end
      p_trap = dut_trap_win;
      //---------------- MODE 3 / 4: idle-period scoring of the power layer
      if (MODE >= 3) begin
        for (int dd = 0; dd < NPG; dd++) begin
          if (!dom_busy[NCG + dd]) begin
            if (!q_idle[dd]) begin
              q_idle[dd] = 1'b1; q_len[dd] = 0; q_gated[dd] = 1'b0;
            end
            q_len[dd] = q_len[dd] + 1;
            if (pm_state_bus[3*(NCG + dd) +: 3] != PM_ON) q_gated[dd] = 1'b1;
          end else if (q_idle[dd]) begin
            q_idle[dd] = 1'b0;
            if (q_gated[dd] && (q_len[dd] >= BE_LBL)) cm_tp[dd] = cm_tp[dd] + 1;
            else if (q_gated[dd])                     cm_fp[dd] = cm_fp[dd] + 1;
            else if (q_len[dd] >= BE_LBL)             cm_fn[dd] = cm_fn[dd] + 1;
            else                                      cm_tn[dd] = cm_tn[dd] + 1;
          end
        end
      end
      //---------------- A8: no X/Z on DUT control outputs (catches X leaking
      //                 through a missing isolation clamp, which if(X)
      //                 semantics would otherwise hide)
      if ((^{dut_valid, dut_wfi, dut_trap_win, dut_pg_stall, pm_state_bus,
             dom_clk_en, dom_iso, dom_ret, dom_pwr, dom_ack, dom_busy, dom_ready,
             dom_mispred}) === 1'bx) begin
        chk_err = chk_err + 1;
        if (verbose || (chk_err <= 10))
          $display("[%0t] CHECKER A8: X/Z on DUT control outputs", $time);
      end
    end
  end

  //=========================================================== ML training trace
  // one line per cycle and power domain: features seen by the model + busy
  always @(negedge clk) begin
    if (rst_n && en) begin
      tr_cyc = tr_cyc + 1;
      if (mltrace && (MODE == 4) && (tr_fd != 0)) begin
        for (int tq = 0; tq < NPG; tq++)
          $fdisplay(tr_fd, "%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d", tr_cyc, tq,
                    ml_feat[32*tq + 21], ml_feat[32*tq +: 6], ml_feat[32*tq + 6 +: 3],
                    ml_feat[32*tq + 9 +: 3], ml_feat[32*tq + 12 +: 3], ml_feat[32*tq + 15],
                    ml_feat[32*tq + 16 +: 4], ml_feat[32*tq + 20]);
      end
    end
  end
endmodule : fido_tb_monitor

`default_nettype wire

// ---------------------------------------------------------------------------
// >>> tb/fido_tb_env.sv
// ---------------------------------------------------------------------------
//=============================================================================
// FIDO V3 (WITCHER) - SystemVerilog testbench
// File      : tb/fido_tb_env.sv
// Module    : fido_tb_env
// Content   : shared twin-core lock-step environment
//   REF = fido_top MODE=BASE (no gating), DUT = configuration under test.
//   Same program, same event stimulus (delivered relative to each core's own
//   WFI sleep, so both cores retire the same instruction stream).
//
//   fido_tb_env
//   |-- u_prog    fido_tb_programs    assembler, test programs T01..T16, event plan
//   |-- u_ev_ref  fido_tb_event_src   events for the REF core
//   |-- u_ev_dut  fido_tb_event_src   events for the DUT core
//   |-- u_sb      fido_tb_scoreboard  retirement compare REF vs DUT, cycle counts
//   |-- u_mon     fido_tb_monitor     pm_state monitor, protocol checker, ML trace
//   `-- (this module) clock, reset, program load, run control, report
//
// Plusargs : +TEST=n  run only test n (default: all)     +SEED=n  random seed
//            +VERBOSE print every mismatch / checker message
//            +MLTRACE (MODE 4) reactive policy + write ml_trace_Tnn.csv per
//                     test into the run folder (training data for ml/train_ml.py)
// Hierarchy : tb_<cfg> > u_env
// Language  : SystemVerilog IEEE 1800-2012, target Cadence Xcelium 22.09
//=============================================================================
`timescale 1ns/1ps
`default_nettype none

module fido_tb_env
  import fido_pkg::*;
  import fido_tb_pkg::*;
#(
  parameter int    MODE    = 0,
  parameter int    GRAIN   = 0,
  parameter int    WAKE_PG = 4,
  parameter string CFG     = "BASE"
) (
  output logic         clk,
  output logic         rst_n,
  output logic         prog_we,
  output logic  [9:0]  prog_addr,
  output logic [31:0]  prog_data,
  output logic  [3:0]  ref_ev_valid,
  output logic [31:0]  ref_ev_data,
  output logic  [3:0]  dut_ev_valid,
  output logic [31:0]  dut_ev_data,
  output logic  [1:0]  ml_force,
  // REF observation
  input  wire          ref_valid,
  input  wire  [31:0]  ref_pc,
  input  wire  [31:0]  ref_insn,
  input  wire   [4:0]  ref_rd,
  input  wire  [31:0]  ref_wdata,
  input  wire          ref_mem_we,
  input  wire  [31:0]  ref_mem_addr,
  input  wire  [31:0]  ref_mem_wdata,
  input  wire   [3:0]  ref_mem_strb,
  input  wire          ref_wfi,
  // DUT observation
  input  wire          dut_valid,
  input  wire  [31:0]  dut_pc,
  input  wire  [31:0]  dut_insn,
  input  wire   [4:0]  dut_rd,
  input  wire  [31:0]  dut_wdata,
  input  wire          dut_mem_we,
  input  wire  [31:0]  dut_mem_addr,
  input  wire  [31:0]  dut_mem_wdata,
  input  wire   [3:0]  dut_mem_strb,
  input  wire          dut_wfi,
  input  wire  [95:0]  pm_state_bus,
  input  wire  [31:0]  dom_clk_en,
  input  wire  [31:0]  dom_iso,
  input  wire  [31:0]  dom_ret,
  input  wire  [31:0]  dom_pwr,
  input  wire  [31:0]  dom_ack,
  input  wire  [31:0]  dom_busy,
  input  wire  [31:0]  dom_ready,
  input  wire  [31:0]  dom_mispred,
  input  wire          dut_trap_win,
  input  wire          dut_pg_stall,
  input  wire [255:0]  ml_feat
);
  //=========================================================== configuration
  localparam int NCG    = (GRAIN == 0) ? NCG_FINE : NCG_COARSE;
  localparam int NPG    = (GRAIN == 0) ? NPG_FINE : NPG_COARSE;
  localparam int ND     = (MODE == MODE_CG) ? NCG : (MODE == MODE_PG) ? NPG :
                          (MODE >= MODE_CGPG) ? (NCG + NPG) : 0;
  localparam int NTESTS = (MODE >= MODE_CGPG) ? 16 : 11;

  //=========================================================== run control state
  logic   sb_en         = 1'b0;
  logic   mon_en        = 1'b0;
  logic   verbose       = 1'b0;
  logic   mltrace       = 1'b0;
  integer seed          = 1;
  integer sel_test      = 0;
  int     t_pass        = 0;
  int     t_fail        = 0;
  int     chk_err_total = 0;

  //=========================================================== sub-environment
  wire [31:0]   ev_n;
  wire [1023:0] ev_dly_v;
  wire [63:0]   ev_src_v;
  wire [255:0]  ev_dat_v;

  fido_tb_programs #(.MODE(MODE), .GRAIN(GRAIN)) u_prog (
    .ev_n     (ev_n),
    .ev_dly_v (ev_dly_v),
    .ev_src_v (ev_src_v),
    .ev_dat_v (ev_dat_v)
  );

  fido_tb_event_src u_ev_ref (
    .clk      (clk),
    .rst_n    (rst_n),
    .wfi      (ref_wfi),
    .ev_n     (ev_n),
    .ev_dly_v (ev_dly_v),
    .ev_src_v (ev_src_v),
    .ev_dat_v (ev_dat_v),
    .ev_valid (ref_ev_valid),
    .ev_data  (ref_ev_data)
  );

  fido_tb_event_src u_ev_dut (
    .clk      (clk),
    .rst_n    (rst_n),
    .wfi      (dut_wfi),
    .ev_n     (ev_n),
    .ev_dly_v (ev_dly_v),
    .ev_src_v (ev_src_v),
    .ev_dat_v (ev_dat_v),
    .ev_valid (dut_ev_valid),
    .ev_data  (dut_ev_data)
  );

  fido_tb_scoreboard u_sb (
    .clk           (clk),
    .rst_n         (rst_n),
    .en            (sb_en),
    .verbose       (verbose),
    .ref_valid     (ref_valid),
    .ref_pc        (ref_pc),
    .ref_insn      (ref_insn),
    .ref_rd        (ref_rd),
    .ref_wdata     (ref_wdata),
    .ref_mem_we    (ref_mem_we),
    .ref_mem_addr  (ref_mem_addr),
    .ref_mem_wdata (ref_mem_wdata),
    .ref_mem_strb  (ref_mem_strb),
    .dut_valid     (dut_valid),
    .dut_pc        (dut_pc),
    .dut_insn      (dut_insn),
    .dut_rd        (dut_rd),
    .dut_wdata     (dut_wdata),
    .dut_mem_we    (dut_mem_we),
    .dut_mem_addr  (dut_mem_addr),
    .dut_mem_wdata (dut_mem_wdata),
    .dut_mem_strb  (dut_mem_strb)
  );

  fido_tb_monitor #(.MODE(MODE), .GRAIN(GRAIN), .WAKE_PG(WAKE_PG)) u_mon (
    .clk          (clk),
    .rst_n        (rst_n),
    .en           (mon_en),
    .verbose      (verbose),
    .mltrace      (mltrace),
    .dut_valid    (dut_valid),
    .dut_wfi      (dut_wfi),
    .dut_trap_win (dut_trap_win),
    .dut_pg_stall (dut_pg_stall),
    .pm_state_bus (pm_state_bus),
    .dom_clk_en   (dom_clk_en),
    .dom_iso      (dom_iso),
    .dom_ret      (dom_ret),
    .dom_pwr      (dom_pwr),
    .dom_ack      (dom_ack),
    .dom_busy     (dom_busy),
    .dom_ready    (dom_ready),
    .dom_mispred  (dom_mispred),
    .ml_feat      (ml_feat)
  );

  //=========================================================== clock
  initial clk = 1'b0;
  always #5 clk = ~clk;

  //=========================================================== run control
  task automatic load_and_reset;
    int carry;
    @(negedge clk);
    // samplers that are still enabled (only after the T10 prelude) take this
    // edge first; reset and the sampler disable follow 1 ns later (no clock
    // edge in between), so no sampler races these assignments
    #1;
    rst_n  = 1'b0;
    sb_en  = 1'b0;
    mon_en = 1'b0;
    for (int n = 0; n < 1024; n++) begin
      @(negedge clk);
      prog_we   = 1'b1;
      prog_addr = n[9:0];
      prog_data = u_prog.prog[n];
    end
    @(negedge clk);
    prog_we = 1'b0;
    // reset check: every domain ON while in reset
    for (int n = 0; n < 32; n++) begin
      if (pm_state_bus[3*n +: 3] != PM_ON) begin
        u_mon.chk_err = u_mon.chk_err + 1;
        $display("[%0t] CHECKER: domain %0d not ON during reset", $time, n);
      end
    end
    carry = u_mon.chk_err + u_sb.sb_err;
    u_sb.clear();
    u_mon.clear();
    u_mon.chk_err = carry;
    @(negedge clk);
    rst_n = 1'b1;
    // enable the negedge samplers half a cycle later, so no sampler races
    // the reset release (cycle counts identical on every simulator)
    @(posedge clk);
    sb_en  = 1'b1;
    mon_en = 1'b1;
  endtask

  task automatic wait_done;
    // the done flags and run_cyc are written by the scoreboard on the
    // negative edge; they are polled on the positive edge (half a cycle
    // later), so the end of a test never depends on the order in which a
    // simulator runs processes woken by the same clock edge
    while (!(u_sb.ref_done && u_sb.dut_done) && (u_sb.run_cyc < TIMEOUT)) @(posedge clk);
    repeat (3) @(negedge clk);
    // disable the negedge samplers half a cycle before the next negedge, so
    // no sampler races this assignment (statistics identical on every simulator)
    @(posedge clk);
    sb_en  = 1'b0;
    mon_en = 1'b0;
  endtask

  //=========================================================== report
  task automatic report_test(input int t, input string name);
    logic t_ok;
    int   cn;
    int   dom;
    int   bad_exp;
    int   pct;
    int   npg_entry;
    int   npg_mis;
    int   npg_fp;
    int   ref_cyc;
    int   dut_cyc;
    t_ok    = 1'b1;
    bad_exp = 0;
    ref_cyc = u_sb.ref_cyc;
    dut_cyc = u_sb.dut_cyc;
    if (!(u_sb.ref_done && u_sb.dut_done)) begin
      t_ok = 1'b0;
      $display("  ERROR: timeout (REF done=%0b DUT done=%0b)", u_sb.ref_done, u_sb.dut_done);
    end
    if (u_sb.ref_code != 32'd1) begin
      t_ok = 1'b0;
      $display("  ERROR: REF program failed, code %08h (check %0d)", u_sb.ref_code,
               u_sb.ref_code - 32'h100);
    end
    if (u_sb.dut_code != 32'd1) begin
      t_ok = 1'b0;
      $display("  ERROR: DUT program failed, code %08h (check %0d)", u_sb.dut_code,
               u_sb.dut_code - 32'h100);
    end
    if ((u_sb.sb_err != 0) || (u_sb.ref_ret != u_sb.dut_ret) || (u_sb.f_cnt != 0)) begin
      t_ok = 1'b0;
      $display("  ERROR: scoreboard errors=%0d REF retired=%0d DUT retired=%0d left=%0d",
               u_sb.sb_err, u_sb.ref_ret, u_sb.dut_ret, u_sb.f_cnt);
    end
    if (u_mon.chk_err != 0) begin
      t_ok = 1'b0;
      $display("  ERROR: %0d protocol-checker errors", u_mon.chk_err);
    end
    if ((MODE == MODE_CG) || (MODE == MODE_PG)) begin
      for (int d = 0; d < 4; d++) begin
        cn = (GRAIN == 0) ? u_prog.exp_f[d] : u_prog.exp_c[d];
        if (cn >= 0) begin
          dom = cn2dom(MODE, GRAIN, cn);
          if (dom != 31) begin
            if (u_mon.m_entry[dom] == 0) begin
              bad_exp = bad_exp + 1;
              $display("  ERROR: expected %0s to be gated at least once", dname(MODE, GRAIN, dom));
            end
          end
        end
      end
    end
    if (MODE >= MODE_CGPG) begin
      // clock layer always; power layer for reactive CG+PG, and for ML only
      // where the test forces the decision (an ML model may rightly decide
      // not to power-gate - that is scored in the idle-period table instead)
      for (int d = 0; d < 4; d++) begin
        cn = (GRAIN == 0) ? u_prog.exp_f[d] : u_prog.exp_c[d];
        if (cn >= 0) begin
          dom = cn2cg(GRAIN, cn);
          if ((dom != 31) && (u_mon.m_entry[dom] == 0)) begin
            bad_exp = bad_exp + 1;
            $display("  ERROR: expected %0s to be gated at least once", dname(MODE, GRAIN, dom));
          end
          dom = cn2pg(GRAIN, cn);
          if ((dom != 31) && ((MODE == MODE_CGPG) || u_prog.exp_pg_req) && (u_mon.m_entry[dom] == 0)) begin
            bad_exp = bad_exp + 1;
            $display("  ERROR: expected %0s to be power-gated at least once", dname(MODE, GRAIN, dom));
          end
        end
      end
      npg_entry = 0;
      npg_mis   = 0;
      npg_fp    = 0;
      for (int d = NCG; d < NCG + NPG; d++) begin
        npg_entry = npg_entry + u_mon.m_entry[d];
        npg_mis   = npg_mis + u_mon.m_mis[d];
        npg_fp    = npg_fp + u_mon.cm_fp[d - NCG];
      end
      // T12 (MODE 4): the forced confident decisions must include wrong gates
      // (power-down on an idle shorter than BE_LBL, or a wake inside the
      // break-even window) - and the scoreboard / checker above must be clean
      if ((MODE == MODE_CGPG_ML) && (t == 12) && !mltrace && ((npg_mis + npg_fp) == 0)) begin
        bad_exp = bad_exp + 1;
        $display("  ERROR: forced confident gating produced no wrong gate to recover from");
      end
      // T13 (MODE 4): confidence 0 -> the shell must refuse every power-gating request
      if ((MODE == MODE_CGPG_ML) && (t == 13) && !mltrace && (npg_entry != 0)) begin
        bad_exp = bad_exp + 1;
        $display("  ERROR: %0d power-gating entries with confidence 0", npg_entry);
      end
      // T16 (MODE 3): reactive CG+PG must escalate CG -> PG on the MUL net
      if ((MODE == MODE_CGPG) && (t == 16) && (u_mon.m_esc == 0)) begin
        bad_exp = bad_exp + 1;
        $display("  ERROR: no CG -> PG escalation seen on the MUL clock net");
      end
    end
    if (bad_exp != 0) t_ok = 1'b0;
    chk_err_total = chk_err_total + u_mon.chk_err;
    u_mon.chk_err = 0;

    $display("  retired %0d instr | REF %0d cycles | DUT %0d cycles | overhead %0d.%01d %% | gating stalls %0d",
             u_sb.dut_ret, ref_cyc, dut_cyc,
             ((dut_cyc - ref_cyc) * 100) / ((ref_cyc > 0) ? ref_cyc : 1),
             (((dut_cyc - ref_cyc) * 1000) / ((ref_cyc > 0) ? ref_cyc : 1)) % 10, u_mon.m_stall);
    if (MODE != MODE_BASE) begin
      $display("  domain       entries    wakes   gated%%  mispred  maxwake");
      for (int d = 0; d < ND; d++) begin
        pct = (u_mon.m_gcyc[d] * 100) / ((dut_cyc > 0) ? dut_cyc : 1);
        $display("  %s %8d %8d %8d %8d %8d", dname(MODE, GRAIN, d), u_mon.m_entry[d],
                 u_mon.m_wake[d], pct, u_mon.m_mis[d], u_mon.m_maxl[d]);
      end
    end
    if (MODE >= MODE_CGPG) begin
      $display("  power-gating decisions per idle period (long = idle >= %0d cycles)", BE_LBL);
      $display("  domain     gated+long gated+short  missed-long  kept-short");
      for (int d = 0; d < NPG; d++)
        $display("  %s %10d %11d %12d %11d", pg_name(GRAIN, d), u_mon.cm_tp[d], u_mon.cm_fp[d],
                 u_mon.cm_fn[d], u_mon.cm_tn[d]);
      $display("  CG->PG escalations on the MUL clock net: %0d", u_mon.m_esc);
    end
    if (t_ok) begin
      t_pass = t_pass + 1;
      $display("  RESULT T%02d %0s : PASS", t, name);
    end else begin
      t_fail = t_fail + 1;
      $display("  RESULT T%02d %0s : FAIL", t, name);
    end
    u_sb.sb_err = 0;
  endtask

  //=========================================================== one test
  task automatic run_test(input int t);
    string name;
    int    n;
    int    nongated;
    name = test_name(t);
    u_prog.build(t);
    $display("");
    $display("---------------------------------------------------------------------------");
    $display(" T%02d %0s   [%0s]   program %0d words", t, name, CFG, u_prog.plen);
    $display("---------------------------------------------------------------------------");
    if (u_prog.plen > 1024) $display("  ERROR: program too long");
    ml_force <= mltrace ? 2'd3 : u_prog.t_force;
    if (mltrace && (MODE == MODE_CGPG_ML)) u_mon.trace_open(t);
    if (t == 10) begin
      // prelude: run an idle program, then reset the DUT while it is gated
      u_prog.build_idle_forever();
      load_and_reset();
      n        = 0;
      nongated = 1;
      while ((n < 2000) && (nongated != 0)) begin
        @(negedge clk);
        n        = n + 1;
        nongated = 1;
        for (int k = 0; k < ND; k++)
          if ((pm_state_bus[3*k +: 3] >= PM_PG_RET) ||
              (((MODE == MODE_CG) || (MODE >= MODE_CGPG)) && (pm_state_bus[3*k +: 3] == PM_CG)))
            nongated = 0;
      end
      if (MODE != MODE_BASE)
        $display("  prelude: DUT gated after %0d cycles (%0s), asserting reset now",
                 n, (nongated == 0) ? "yes" : "no");
      u_prog.build(10);
    end
    load_and_reset();
    wait_done();
    u_mon.trace_close();
    report_test(t, name);
  endtask

  //=========================================================== main
  initial begin
    rst_n     = 1'b0;
    prog_we   = 1'b0;
    prog_addr = 10'd0;
    prog_data = 32'd0;
    ml_force  = 2'd0;
    u_sb.clear();
    u_mon.clear();
    if (!$value$plusargs("SEED=%d", seed))     seed     = 1;
    if (!$value$plusargs("TEST=%d", sel_test)) sel_test = 0;
    if ($test$plusargs("VERBOSE")) verbose = 1'b1;
    if ($test$plusargs("MLTRACE")) mltrace = 1'b1;
    u_prog.seed = seed;
    $display("===========================================================================");
    $display(" FIDO V3 shared kit - lock-step testbench   config %0s  (MODE=%0d GRAIN=%0d)", CFG, MODE, GRAIN);
    if (MODE >= MODE_CGPG)
      $display(" REF = fido_top BASE, DUT = %0s, %0d clock + %0d power domains, seed %0d", CFG, NCG, NPG, seed);
    else
      $display(" REF = fido_top BASE, DUT = %0s, %0d gated domains, seed %0d", CFG, ND, seed);
    if (mltrace) $display(" ML trace mode: reactive policy, writing ml_trace_Tnn.csv");
    $display("===========================================================================");
    for (int tn = 1; tn <= NTESTS; tn++) begin
      if ((sel_test == 0) || (sel_test == tn)) run_test(tn);
    end
    $display("");
    $display("===========================================================================");
    $display(" SUMMARY %0s : %0d passed, %0d failed, %0d checker errors", CFG, t_pass, t_fail, chk_err_total);
    if (t_fail == 0) $display(" ALL TESTS PASSED");
    else             $display(" TESTS FAILED");
    $display("===========================================================================");
    $finish;
  end
endmodule : fido_tb_env

`default_nettype wire

